<?php
namespace ScratchByPHP\Support;
final class RateLimiter { private static array $last=[]; private int $max=30,$window=60; private array $hits=[]; public static function wait(string $key,float $minIntervalSeconds):void{$now=microtime(true);$last=self::$last[$key]??0.0;$d=$now-$last;if($d<$minIntervalSeconds)usleep((int)(($minIntervalSeconds-$d)*1e6));self::$last[$key]=microtime(true);} public function maxRequests(int $max):self{$this->max=max(1,$max);return $this;} public function perSeconds(int $seconds):self{$this->window=max(1,$seconds);return $this;} public function acquire(string $key='default'):void{$now=microtime(true);$this->hits[$key]=array_values(array_filter($this->hits[$key]??[],fn($t)=>$t>$now-$this->window));if(count($this->hits[$key])>=$this->max){$wait=$this->window-($now-$this->hits[$key][0]);if($wait>0)usleep((int)($wait*1e6));}$this->hits[$key][]=microtime(true);} public static function retryAfter(array $headers):?int{$v=$headers['retry-after'][0]??$headers['Retry-After'][0]??null;return is_numeric($v)?(int)$v:null;} }
